import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Compute scores and counts
    my_score = 0
    op_score = 0
    my_c = 0
    my_d = 0
    op_c = 0
    op_d = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0

    for a, b in history:
        if a == 'C':
            my_c += 1
            if b == 'C':
                my_score += 3
                op_score += 3
                cc += 1
            else:
                my_score += 0
                op_score += 5
                cd += 1
        else:
            my_d += 1
            if b == 'C':
                my_score += 5
                op_score += 0
                dc += 1
            else:
                my_score += 1
                op_score += 1
                dd += 1
        if b == 'C':
            op_c += 1
        else:
            op_d += 1

    last_my, last_op = history[-1]
    remaining = 100 - n

    # If opponent has never defected, keep cooperating (safest) but exploit very late
    if op_d == 0:
        if remaining <= 1 and n >= 95 and my_score <= op_score + 2:
            return 'D'
        return 'C'

    # If opponent has never cooperated, defect always
    if op_c == 0:
        return 'D'

    # Cooperation ratio of opponent
    coop_rate = op_c / n

    # Recent window (last 12 or so)
    window = history[-12:] if n >= 12 else history
    wlen = len(window)
    recent_op_d = 0
    recent_op_c = 0
    recent_my_d = 0
    for a, b in window:
        if b == 'D':
            recent_op_d += 1
        else:
            recent_op_c += 1
        if a == 'D':
            recent_my_d += 1

    # Consecutive opponent actions from the end
    opp_def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_def_streak += 1
        else:
            break

    # Detect possible exploiters: opponent defects more than we do, and we've been nice
    # Strong punishment for sustained defection
    if opp_def_streak >= 3:
        # If they've been defecting a lot overall, keep defecting
        if coop_rate < 0.4:
            return 'D'
        # Otherwise punish, then test forgiveness
        if opp_def_streak >= 5:
            # Occasionally try to restore cooperation
            if rng.random() < 0.1:
                return 'C'
        return 'D'

    # Opponent defected last round
    if last_op == 'D':
        # If coop rate is decent, retaliate once then return to C
        if coop_rate >= 0.5:
            # If we just defected as punishment and they now might respond, alternate
            if last_my == 'D':
                # We already punished; return to C to signal willingness
                if coop_rate >= 0.7 and opp_def_streak <= 2:
                    return 'C'
                # Otherwise defect again to keep pressure
                if rng.random() < 0.5:
                    return 'D'
                return 'C'
            return 'D'
        # Low coop rate: defect
        return 'D'

    # Opponent cooperated last round.
    # Detect if it's a mostly-cooperative opponent (meant to lock in CC).
    if coop_rate >= 0.85 and recent_op_d <= 1:
        # Stay cooperative. Small probabilistic probe only very late.
        if remaining <= 2 and n >= 98:
            if rng.random() < 0.5:
                return 'D'
        return 'C'

    # Moderate opponent. If we're behind significantly, defect occasionally to catch up
    if my_score + 5 < op_score:
        if rng.random() < 0.3:
            return 'D'
        return 'C'

    # If opponent has been defecting more than half recently, retaliate more
    if recent_op_d * 2 > wlen:
        if rng.random() < 0.4:
            return 'D'
        return 'C'

    # Base: tit-for-tat-like cooperation after a cooperative move
    return 'C'
